public class InnerChannelLinkedChannelSettingsFactory(Action<Humidifier.MediaLive.ChannelTypes.LinkedChannelSettings> factoryAction = null) : SubResourceFactory<Humidifier.MediaLive.ChannelTypes.LinkedChannelSettings>
{

    internal InnerChannelFollowerChannelSettingsFactory FollowerChannelSettingsFactory { get; set; }

    internal InnerChannelPrimaryChannelSettingsFactory PrimaryChannelSettingsFactory { get; set; }

    protected override Humidifier.MediaLive.ChannelTypes.LinkedChannelSettings Create()
    {
        var linkedChannelSettingsResult = CreateLinkedChannelSettings();
        factoryAction?.Invoke(linkedChannelSettingsResult);

        return linkedChannelSettingsResult;
    }

    private Humidifier.MediaLive.ChannelTypes.LinkedChannelSettings CreateLinkedChannelSettings()
    {
        var linkedChannelSettingsResult = new Humidifier.MediaLive.ChannelTypes.LinkedChannelSettings();

        return linkedChannelSettingsResult;
    }
    public override void CreateChildren(Humidifier.MediaLive.ChannelTypes.LinkedChannelSettings result)
    {
        base.CreateChildren(result);

        result.FollowerChannelSettings ??= FollowerChannelSettingsFactory?.Build();
        result.PrimaryChannelSettings ??= PrimaryChannelSettingsFactory?.Build();
    }

} // End Of Class

